mapper.select:
SELECT * FROM comments
WHERE status = #{status}
ORDER BY created_at DESC

mapper.update:
UPDATE comments
SET status = #{status}
WHERE id = #{id}

UPDATE comments
SET content = #{content}
WHERE id = #{id}

UPDATE comments
SET is_top = #{isTop}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM comments
WHERE created_at >= #{startDate} 
AND created_at < #{endDate}
